#!/usr/bin/env node
// Native Lean is the authority. WABT serializes Lean-emitted WAT; it is not a proof checker.
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import wabtFactory from 'wabt';
const root=path.dirname(fileURLToPath(import.meta.url));
const read=relative=>fs.readFile(path.join(root,relative),'utf8');
const hash=s=>createHash('sha256').update(s).digest('hex');
const normalize=s=>s.replace(/\r\n/g,'\n').trim();
const checkedNames=['LeanDSP.compileExpr_correct','LeanDSP.compile_correct','LeanDSP.compile_trace_correct','LeanDSP.all_instantiations','LeanDSP.compileExpr_length','LeanDSP.ring_index_lt','LeanDSP.lower_correct','LeanDSP.io_region_safe','LeanDSP.buffer_region_safe','LeanDSP.instance_memory_invariant','LeanDSP.WasmSubset.lowerCode_correct','LeanDSP.WasmSubset.compileExpr_toWasm_correct','LeanDSP.WasmSubset.lowerBlock_correct','LeanDSP.WasmSubset.compileBlock_toWasm_correct'];
const allowed=new Set(['propext','Classical.choice','Quot.sound']);
const execute=args=>{const r=spawnSync('lake',['env','lean',...args],{cwd:root,encoding:'utf8',maxBuffer:16*1024*1024,timeout:180000});if(r.error)throw r.error;if(r.status!==0)throw new Error(r.stdout+'\n'+r.stderr);return r.stdout;};
const version=execute(['--version']);if(!/\b4\.34\.0\b/.test(version))throw new Error('This build pins Lean 4.34.0: '+version);
const ids=JSON.parse(await read('pattern-map.json'));
let header='';for(const f of['Core','Checker','WasmSubset','Syntax','Emitter'])header+=(await read('LeanDSP/'+f+'.lean')).replace(/^import LeanDSP\.[^\n]+\n/gm,'')+'\n';
const sources={};let bodies='open LeanDSP\n';
for(const id of ids){if(!/^[A-Za-z][A-Za-z0-9_]*$/.test(id))throw new Error('Invalid pattern id');const raw=await read('patterns/'+id+'.lean'),start=raw.indexOf('dsp ');if(start<0)throw new Error(id+': missing dsp declaration');const source=normalize(raw.slice(start)),m=source.match(/^dsp\s+([A-Za-z_][A-Za-z0-9_]*)\s+where/);if(!m)throw new Error(id+': invalid name');sources[id]={source,name:m[1]};bodies+='\n'+source+'\n';}
const symbols=[...checkedNames,...Object.values(sources).map(x=>x.name)];
const program=header+'\nset_option maxRecDepth 8192\nset_option maxHeartbeats 4000000\n'+bodies+'\n'+symbols.map(n=>'#print axioms '+n).join('\n')+'\ndef main : IO Unit := IO.println ((Lean.Json.arr #['+ids.map(id=>'LeanDSP.artifact '+JSON.stringify(id)+' '+sources[id].name).join(',\n')+']).compress)\n';
await fs.writeFile(path.join(root,'GeneratedBuild.lean'),program);
const output=execute(['--run','GeneratedBuild.lean']);
const audits=[];for(const name of symbols){const escaped=name.replaceAll('.','\\.');const hit=output.match(new RegExp("'"+escaped+"' (?:depends on axioms:\\s*\\[([^\\]]*)\\]|does not depend on any axioms)"));if(!hit)throw new Error('Missing kernel axiom audit: '+name);const axioms=hit[1]?hit[1].split(',').map(s=>s.trim()).filter(Boolean):[];for(const a of axioms)if(!allowed.has(a))throw new Error('Unapproved axiom in '+name+': '+a);audits.push({name,axioms});}
const line=output.split('\n').findLast(l=>l.startsWith('[{'));if(!line)throw new Error('No native artifact JSON');const artifacts=JSON.parse(line);if(artifacts.length!==ids.length)throw new Error('Incomplete native output');
const wabt=await wabtFactory(),catalog={schema:'leandsp-native-catalog/1',leanVersion:'4.34.0',buildHash:hash(program),compilerTheorem:'LeanDSP.lower_correct',traceTheorem:'LeanDSP.compile_trace_correct',verification:{kernelChecked:true,mechanism:'Native lake env lean with kernel certificates and audited axioms',axiomAllowlist:[...allowed],trustedBoundary:['Lean implementation','WAT serializer','WABT','WebAssembly runtime','host scheduler and mixer'],claim:'Source-to-stack-IR compiler refinement, not full native/browser runtime verification'},patterns:{}};
for(const a of artifacts){const parsed=wabt.parseWat(a.id+'.wat',a.wat,{bulk_memory:true,multi_value:true});let bytes;try{parsed.resolveNames();parsed.validate();bytes=new Uint8Array(parsed.toBinary({write_debug_names:true}).buffer);}finally{parsed.destroy();}if(!WebAssembly.validate(bytes))throw new Error('Invalid emitted Wasm: '+a.id);const inst=(await WebAssembly.instantiate(bytes)).instance.exports;inst.prepare(48000);let bounded=false;try{inst.memory.grow(1)}catch{bounded=true}if(!bounded)throw new Error('Wasm memory was not fixed');const source=sources[a.id].source;catalog.patterns[a.id]={...a,source,sourceHash:hash(source),watHash:hash(a.wat),wasmHash:hash(bytes),wasmBase64:Buffer.from(bytes).toString('base64'),sourcePath:'/lean/patterns/'+a.id+'.lean',proofSymbols:checkedNames,params:a.params.map(p=>({...p,def:Number(p.def),lo:Number(p.lo),hi:Number(p.hi)})),states:a.states.map(s=>({...s,init:Number(s.init)}))};}
const serialized=JSON.stringify(catalog);await fs.mkdir(path.join(root,'out'),{recursive:true});await fs.writeFile(path.join(root,'out/catalog.json'),serialized);await fs.writeFile(path.join(root,'out/catalog.sha256'),hash(serialized)+'\n');await fs.writeFile(path.join(root,'out/build-report.json'),JSON.stringify({leanVersion:version.trim(),buildHash:hash(program),catalogHash:hash(serialized),axiomAudits:audits,checkedAt:new Date().toISOString(),patterns:artifacts.length},null,2));
console.log('Built '+artifacts.length+' Lean-certified families. Catalog SHA-256: '+hash(serialized));
console.log('Publish out/catalog.json and its hash through your trusted release process. A JSON claim by itself is not proof verification.');

